/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_ASSESSMENT_UNDERWRITING
   anchor      : HUB_ASSESSMENT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 3 emitted of 3 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_ASSESSMENT_HK
   hashdiff    : SAT_ASSESSMENT_UNDERWRITING_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__PD_SCRUTINY_NUMBER))) as HUB_ASSESSMENT_HK
        , MD_SPCL_CONDTN_MEMBER_LEVEL as SPECIAL_CONDITIONS_RECOMMENDED
        , cast(null as varchar) as UNDERWRITING_REMARKS
        , cast(null as varchar) as RISK_ACCEPTANCE_AUTHORITY
        , 'BA_HCP_PROD_8432_ECP_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8432_ecp_loader') }}
    where (nullif(trim(PD_SCRUTINY_NUMBER),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__SCRUTINY_NO))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as SPECIAL_CONDITIONS_RECOMMENDED
        , UW_REMARK as UNDERWRITING_REMARKS
        , cast(null as varchar) as RISK_ACCEPTANCE_AUTHORITY
        , 'BJAZ_BANDHAN_MEDI_CLAM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bandhan_medi_clam') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__SCRUTINY_NO))) as HUB_ASSESSMENT_HK
        , cast(null as varchar) as SPECIAL_CONDITIONS_RECOMMENDED
        , cast(null as varchar) as UNDERWRITING_REMARKS
        , ACCPEPTED_SI_BY as RISK_ACCEPTANCE_AUTHORITY
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
),

resolved as (
    select
        HUB_ASSESSMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SPECIAL_CONDITIONS_RECOMMENDED end) as SPECIAL_CONDITIONS_RECOMMENDED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then UNDERWRITING_REMARKS end) as UNDERWRITING_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_v2' then RISK_ACCEPTANCE_AUTHORITY end) as RISK_ACCEPTANCE_AUTHORITY,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ASSESSMENT_HK
),

hashed as (
    select
        *,
        case when SPECIAL_CONDITIONS_RECOMMENDED is not null or UNDERWRITING_REMARKS is not null or RISK_ACCEPTANCE_AUTHORITY is not null
                     then md5(upper(coalesce(cast(SPECIAL_CONDITIONS_RECOMMENDED as varchar), '') || '|' || coalesce(cast(UNDERWRITING_REMARKS as varchar), '') || '|' || coalesce(cast(RISK_ACCEPTANCE_AUTHORITY as varchar), '')))
                end as SAT_ASSESSMENT_UNDERWRITING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_ASSESSMENT_HK is not null
  and SAT_ASSESSMENT_UNDERWRITING_HASHDIFF is not null
